#!/usr/bin/env python3
"""
Installer for Phase 13 (PR #16): Autonomous Cron Scheduling, Jalali Awareness & Multi-Platform Delivery
=====================================================================================================
This script creates all files for dream/cron/ and updates dream/scheduler.py.
Run this script from the root of your Dream repository:
    python apply_pr16.py
"""

import base64
import json
import os
from pathlib import Path

B64_PAYLOAD = ""

def main():
    root = Path.cwd()
    print("🚀 Applying Phase 13: Autonomous Scheduling & Delivery Dispatcher (dream/cron/)...")
    # Remove legacy standalone module if present
    legacy_file = root / "dream" / "cron.py"
    if legacy_file.exists() and legacy_file.is_file():
        legacy_file.unlink()
        print("  🗑️ Removed legacy dream/cron.py (migrated to dream/cron/ package)")

    raw_bytes = base64.b64decode(B64_PAYLOAD.encode("ascii"))
    files = json.loads(raw_bytes.decode("utf-8"))
    for rel_path, content in files.items():
        dest = root / rel_path
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(content, encoding="utf-8")
        print(f"  ✅ Created/Updated: {rel_path}")
    print("\n🎉 PR #16 files successfully installed!")
    print("Run tests with: pytest tests/test_cron_and_delivery_system.py tests/test_scheduler.py tests/security/test_sec_cron_storage.py")

if __name__ == "__main__":
    main()
